Voici un exemple de code en C# qui crée un serveur HTTP simple à l'aide de `HttpListener` et affiche le texte "Hello" sur la page "/hello" au port 8080 :
```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;

class HttpServer
{
    static void Main(string[] args)
    {
        // Création du listener HTTP
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/"); // Nous écouterons sur le port 8080 avec un prefix "/"

        // Lancement du listener
        listener.Start();

        Console.WriteLine("Server started. Waiting for incoming requests...");

        while (true)
        {
            HttpListenerRequest request = listener.GetContext().Request;

            // Traitement de la requête /hello
            if (request.Url.AbsolutePath == "/hello")
            {
                string responseString = "Hello, World!";
                HttpListenerResponse response = request.Response;
                byte[] buffer = Encoding.UTF8.GetBytes(responseString);
                response.ContentLength64 = buffer.Length;
                response.OutputStream.Write(buffer, 0, buffer.Length);
                response.OutputStream.Close();
            }
            else
            {
                // Si la requête est inconnue, nous envoyerons un code d'état HTTP 404
                HttpListenerResponse response = request.Response;
                response.StatusCode = 404;
                response.StatusDescription = "Not Found";
                response.OutputStream.Write(Encoding.UTF8.GetBytes("Page not found."), 0, 27);
                response.OutputStream.Close();
            }
        }
    }
}
```
