#include <boost/interprocess/managed_shared_memory.hpp>
#include <boost/interprocess/message_queue.hpp>

using namespace std;
using namespace boost::interprocess;

int main() {
    // Create a shared memory segment
    managed_shared_memory segment(create_only, "MySharedMemory", 1024);

    // Create a semaphore
    interprocess_semaphore sem(1, 0);

    // Create a message queue
    message_queue queue(create_only, "MyMessageQueue", 10);

    // Store a value in shared memory
    int* value = segment.construct<int>("my_value")(42);

    // Acquire the semaphore
    sem.post();

    // Send a message to the queue
    char message[10] = "Hello, client!";
    queue.send(message, 10, no_block);

    // Wait for a message from the client
    char incoming[10];
    queue.receive(incoming, 10, no_block);

    cout << "Received message: " << incoming << endl;

    // Release the semaphore
    sem.assert_signal_available();

    return 0;
}
