Вот пример многопотоковой программы на языке C++ для вычисления приближенного значения интеграла методами прямоугольников, трапеций и парабол (метод Симпсона):
```c
#include <iostream>
#include <Windows.h>
#include <vector>
#include <cmath>
#include <cstdlib>
#include <ctime>

// Мьютекс для синхронизации вывода
HANDLE g_mutex;

//Semaphore для синхронизации доступа к выводу
HANDLE g_semaphore;

// Функция вычисления интеграла методом прямоугольников
double calculateRectangles(double a, double b, double h, int n) {
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += h * (i + 0.5) * (i + 0.5) * exp(-(i + 0.5) * (i + 0.5));
        Sleep(rand() % 100); // небольшие случайные задержки
    }
    return result;
}

// Функция вычисления интеграла методом трапеций
double calculateTrapezoids(double a, double b, double h, int n) {
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += h * (i + 0.5) * (i + 0.5) * exp(-(i + 0.5) * (i + 0.5));
        Sleep(rand() % 100); // небольшие случайные задержки
    }
    return result;
}

// Функция вычисления интеграла методом Симпсона
double calculateSimpson(double a, double b, double h, int n) {
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += 2 * h * (i + 0.5) * (i + 0.5) * exp(-(i + 0.5) * (i + 0.5));
        Sleep(rand() % 100); // небольшие случайные задержки
    }
    return result;
}

// Функция потока для вычисления интеграла методами прямоугольников, трапеций и парабол
DWORD WINAPI calculateIntegral(LPVOID lpParameter) {
    int *params = (int *)lpParameter;
    double a = 0;
    double b = 1;
    int n = params[0];
    int method = params[1];

    double result = 0;

    if (method == 0) {
        result = calculateRectangles(a, b, (b - a) / n, n);
    } else if (method == 1) {
        result = calculateTrapezoids(a, b, (b - a) / n, n);
    } else if (method == 2) {
        result = calculateSimpson(a, b, (b - a) / n, n);
    }

    // Синхронизация вывода
    WaitForSingleObject(g_semaphore, INFINITE);
    LockFile(g_mutex, 0, 0, 1, 1);
    std::cout << "Method: " << method << ", N: " << n << ", Integral: " << result << std::endl;
    UnlockFile(g_mutex, 0, 0, 1, 1);
    ReleaseSemaphore(g_semaphore, 1, NULL);

    return 0;
}

int main() {
    g_mutex = CreateMutex(NULL, FALSE, NULL);
    g_semaphore = CreateSemaphore(NULL, 0, 1, NULL);

    int n = 10; // количество разделений интервала интеграла
    int methods = 3; // количество методов вычисления интеграла

    std::vectorHANDLE threads;

    for (int i = 0; i < methods; i++) {
        int *params = new int[2];
        params[0] = n;
        params[1] = i;
        threads.push_back(CreateThread(NULL, 0, calculateIntegral, params, 0, NULL));
    }

    for (int i = 0; i < methods; i++) {
        WaitForSingleObject(threads[i], INFINITE);
        CloseHandle(threads[i]);
    }

    CloseHandle(g_mutex);
    CloseHandle(g_semaphore);

    return 0;
}
```
В этом примере мы используем 3 метода вычисления интеграла: прямоугольники, трапеции и Симпсона. Каждый поток запускается с параметром `n`, контролирующим количество разделений интервала интеграла, и параметром `method`, контролирующим используемый метод вычисления интеграла.

Функция `calculateIntegral` вычисляет интеграл методом,指定енным в параметре `method`, и выводит результат на экран, синхронизуя вывод с помощью мьютекса `g_mutex` и семафора `g_semaphore`.

В главном потоке мы создаем потоки с помощью функции `CreateThread` и запускаем их. Затем мы ждем, пока όλα потоки не завершатся, и закрываем handles потоков и мьютекса.

