// Definición estructura de un nodo del árbol binario
struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

// Función para crear un nuevo nodo
TreeNode* createNode(int value) {
    TreeNode* newNode = new TreeNode();
    newNode->value = value;
    newNode->left = nullptr;
    newNode->right = nullptr;
    return newNode;
}

// Función búsqueda en árbol binario (recursiva)
int binarySearch(TreeNode* root, int target) {
    if (root == nullptr) {
        return -1; // Nodo no encontrado
    }

    if (root->value == target) {
        return root->value; // Nodo encontrado
    }

    int result = binarySearch(root->left, target);
    if (result != -1) {
        return result;
    }

    return binarySearch(root->right, target);
}

// Función búsqueda en árbol binario (iterativa)
int binarySearchIterative(TreeNode* root, int target) {
    while (root != nullptr) {
        if (root->value == target) {
            return root->value; // Nodo encontrado
        }

        if (target < root->value) {
            root = root->left;
        } else {
            root = root->right;
        }
    }

    return -1; // Nodo no encontrado
}

