    super(props);
    this.state = { sessionToken: null };
    this.sessionManager = new SessionManager();
  }

  async componentDidMount() {
    if (this.sessionManager.is authenticated()) {
      const identity = this.sessionManager.getIdentity();
      this.setState({ sessionToken: this.sessionManager.sessionToken, identity });
    }
  }

  handleLogin() {
    this.sessionManager.login().then(() => {
      this.setState({ sessionToken: this.sessionManager.sessionToken });
    });
  }

  handleLogout() {
    this.sessionManager.logout();
    this.setState({ sessionToken: null });
  }

  render() {
    const { sessionToken, identity } = this.state;

    return (
      <div>
        {sessionToken && (
          <MaterialDesignCard>
            <div>
              <h2>Welcome, {identity.username}!</h2>
              <p>Access token: {sessionToken}</p>
            </div>
          </MaterialDesignCard>
        )}
        {!sessionToken && (
          <MaterialDesignCard>
            <div>
              <h2>Login</h2>
              <button onClick={this.handleLogin}>Login with Google</button>
            </div>
          </MaterialDesignCard>
        )}
        {sessionToken && (
          <MaterialDesignCard>
            <div>
              <h2>Logout</h2>
              <button onClick={this.handleLogout}>Logout</button>
            </div>
          </MaterialDesignCard>
        )}
      </div>
    );
  }
}
